    if i > 0 and row and row[-1] == ',':
        print(f'ERROR: Row {i} has trailing comma')
        print(f'  Line: {row}')
        all_valid = False

if all_valid:
    print('No trailing commas found - VALID')

# Check that all fields have proper quoting
for i, row in enumerate(rows):
    for j, field in enumerate(row):
        if '"' in field or ',' in field or '\n' in field:
            print(f'ERROR: Row {i}, field {j} has unescaped quote or special chars: {field}')
            all_valid = False
            break
    if not any('\"' in f or ',' in f or '\n' in f for f in row):
        print(f'Row {i}: all fields appear properly quoted')

if all_valid:
    print('All fields appear properly quoted - VALID')

print('Final validation complete.')
