import csv
import io

with open('outputs/t09_poi_nearest_stop.csv', 'r', encoding='utf-8') as f:
    content = f.read()

# Parse using csv module
reader = csv.reader(io.StringIO(content))
rows = list(reader)

print(f'Total rows: {len(rows)}')
print(f'Header: {rows[0]}')

# Check all rows have exactly 6 fields
all_valid = True
for i, row in enumerate(rows):
    if len(row) != 6:
        print(f'ERROR: Row {i} has {len(row)} fields instead of 6')
        print(f'  Line: {row}')
        all_valid = False

if all_valid:
    print('All rows have exactly 6 fields')

# Check no trailing commas
for i, row in enumerate(rows):
    if i > 0 and row and row[-1] == ',':
        print(f'ERROR: Row {i} has trailing comma')
        all_valid = False

if all_valid:
    print('No trailing commas found')

# Check for unescaped quotes
for i, row in enumerate(rows):
    for j, field in enumerate(row):
        if '\"' in field or ',' in field or '\n' in field:
            print(f'ERROR: Row {i}, field {j} has unescaped quote: {field}')
            all_valid = False
            break

if all_valid:
    print('All fields appear properly quoted')

# Check no empty fields
for i, row in enumerate(rows):
    if any(field.strip() == '' for field in row):
        print(f'ERROR: Row {i} has empty field')
        all_valid = False

if all_valid:
    print('No empty fields found')

print('\nAll validations passed!')
print(f'Total POIs processed: {len(rows)}')
"
